CREATE OR REPLACE FUNCTION compute_rrs(p_reckey bigint)
RETURNS numeric AS $$
BEGIN
    RETURN (
        SELECT (r.recscore + r.confval + s.recutil) / 3.0
        FROM recommendations r
        JOIN interactions i ON r.reckey = i.reclink
        JOIN sessions s ON i.seshlink2 = s.seshkey
        WHERE r.reckey = p_reckey
        LIMIT 1
    );
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION compute_rrs(p_reckey bigint)
RETURNS numeric AS $$
BEGIN
    RETURN (
        SELECT (r.recscore + r.confval + s.recutil) / 3.0
        FROM recommendations r
        JOIN interactions i ON r.reckey = i.reclink
        JOIN sessions s ON i.seshlink2 = s.seshkey
        WHERE r.reckey = p_reckey
        LIMIT 1
    );
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION compute_rrs()
RETURNS TABLE(reckey bigint, rrs numeric) AS $$
BEGIN
    RETURN QUERY
    SELECT r.reckey, ROUND(CAST((r.recscore + r.confval + s.recutil) / 3.0 AS numeric), 4)
    FROM recommendations r
    JOIN interactions i ON r.reckey = i.reclink
    JOIN sessions s ON i.seshlink2 = s.seshkey;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION compute_rrs() RETURNS SETOF numeric AS $$
    SELECT AVG(r.recscore + r.confval + s.recutil) / 3.0
    FROM recommendations r
    JOIN interactions i ON r.reckey = i.reclink
    JOIN sessions s ON i.seshlink2 = s.seshkey;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION compute_rrs() RETURNS TABLE(reckey bigint, rrs numeric) AS $$
BEGIN
    RETURN QUERY
    SELECT r.reckey::bigint, (r.recscore + r.confval + s.recutil) / 3
    FROM recommendations r
    JOIN interactions i ON r.reckey = i.reclink
    JOIN sessions s ON i.seshlink2 = s.seshkey;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION compute_rrs() RETURNS TABLE(reckey bigint, rrs numeric) AS $$
BEGIN
    RETURN QUERY
    SELECT DISTINCT ON (r.reckey) r.reckey, (r.recscore + r.confval + s.recutil) / 3.0::numeric
    FROM recommendations r
    JOIN interactions i ON r.reckey = i.reclink
    JOIN sessions s ON i.seshlink2 = s.seshkey
    ORDER BY r.reckey;
END;
$$ LANGUAGE plpgsql;
